e.<\/p>"},"elements":[],"widgetType":"text-editor"},{"id":"4b73d28","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"}],"isInner":false},{"id":"da4c5af","elType":"section","settings":{"layout":"full_width"},"elements":[{"id":"a1b01ca","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[],"isInner":false}],"isInner":false},{"id":"71b78c0","elType":"section","settings":{"layout":"full_width"},"elements":[{"id":"a248b04","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"cf0b5c3","elType":"widget","settings":{"title":"Our Vision & Mission","image":{"url":"https:\/\/geims.geu.ac.in\/wp-content\/uploads\/2023\/12\/Clinical-Exposure.jpg","id":5893,"alt":"","source":"library","size":""},"slides":[{"block_title":"","_id":"75ee85c","block_text":"Attain foremost status in Uttarakhand for healthcare and medical education.","block_title2":"","block_text2":"Provide exceptional patient care, advanced infrastructure, and superior medical education."},{"block_title":"","_id":"cf4b4bd","block_text":"Extend accessible, quality patient care to all individuals.","block_title2":"","block_text2":"Ensure compassionate healthcare delivery, making it reachable for every individual and maintaining exceptional standards of quality care."}]},"elements":[],"widgetType":"educamb_our_statement"}],"isInner":false}],"isInner":false},{"id":"454a7a8","elType":"container","settings":{"flex_direction":"column","hide_desktop":"hidden-desktop","hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[],"isInner":false},{"id":"5bbb458","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"0421bf7","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"0be31fd","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"0cc24f8","elType":"widget","settings":{"title":"Our Leadership","align":"center","title_color":"#121212","typography_typography"