ize":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS General Medicine Department: Pioneering Excellence in Healthcare Leadership<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>Within the General Medicine Department, students diagnose and treat various medical conditions. Clinical training immerses learners in authentic patient care, guided by experienced physicians. Through ward rounds and classroom sessions, both practical skills and theoretical foundations are acquired. Participation in research projects fuels curiosity, while collaboration with diverse healthcare teams enhances comprehension of holistic healthcare approaches.<\/p><p>This dynamic setting not only sharpens diagnostic abilities but also nurtures empathy, effective communication, and essential professionalism crucial for future doctors.<\/p><p><strong>Key Highlights<\/strong><\/p><p>The Department of General Medicine focuses on diagnosing and managing various illnesses. Clinical exposure, multidisciplinary learning, and emphasis on holistic patient care shape well-rounded future physicians.<\/p><ul><li><strong>Clinical Training:<\/strong> Hands-on experience in diagnosing and managing various medical conditions, exposing students to real patient scenarios in hospitals or clinics.<\/li><li><strong>Didactic Teaching<\/strong>: Classroom-based learning covering the theoretical aspects of internal medicine, including lectures, seminars, and case-based discussions to build a strong foundational knowledge base.<\/li><li><strong>Ethics and Professionalism:<\/strong> Education on medical ethics, professionalism, and the importance of empathy and compassion in patient care.<\/li><li><strong>Practical Skills Training:<\/strong> Training in venipuncture, IV insertion, and basic life support techniques essential for medical practice.<\/li><\/ul>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":"1","unit":"px","size":"10"},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":""},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":"0","_flex_shrink":"0","sticky":"bottom","sticky_offset":"100","sticky_effects_offset":"100","sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"center","title_color":"#FFFFFF"},"elements":[],"widgetType":"heading"},{"id":"0cc6981","elType":"widget","settings":{"editor":"<p>Department of General Medicine<\/p>","align":"center","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"700"},"elements":[],"widgetType":"text-editor"},{"id":"c5b2f2e","elType":"widget","settings":{"editor":"<p>Graphic Era Institute of Medical Sciences<br \/>16th Milestone, Chakrata Rd, Dehradun, Uttarakhand 248008<\/p>","align":"center","text_color":"#FFFFFF","typography_typography":"custom","typography_font_fam