e";s:10:"meta_value";s:7:"wp-page";}i:133;O:8:"stdClass":3:{s:7:"post_id";s:4:"5779";s:8:"meta_key";s:18:"_elementor_version";s:10:"meta_value";s:6:"3.25.4";}i:134;O:8:"stdClass":3:{s:7:"post_id";s:4:"5779";s:8:"meta_key";s:15:"_elementor_data";s:10:"meta_value";s:15377:"[{"id":"b651ee6","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":"0","column":"0","row":"0"},"padding":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":""}},"elements":[{"id":"deff3aa","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"66.6666"}},"elements":[{"id":"8dc56b0","elType":"widget","settings":{"editor":"<p>Within the Paediatrics and Neonatology Department, students acquire skills to offer holistic healthcare for infants, children, and adolescents. This encompasses diagnosis, treatment, and compassionate care in a supportive educational setting.<\/p>","text_color":"#6B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS Pediatrics and Neonatology Department: Nurturing the Future, One Child at a Time<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>The Paediatrics and Neonatology Department at GEIMS specialises in the healthcare of infants, children, and adolescents, covering a spectrum of medical needs from routine check-ups to critical care interventions.<\/p><p>This department equips students with comprehensive knowledge in child development, pediatric diseases, and neonatal care. Students engage in hands-on learning, participating in clinical rotations, pediatric wards, and neonatal units, gaining exposure to diverse cases under the guidance of experienced paediatricians.<\/p><p>Emphasis is placed on nurturing compassionate care, effective communication with young patients and their families, and understanding the unique medical, emotional, and social needs of pediatric and neonatal populations.<\/p><p>\u00a0<\/p><p><strong>Key Highlights<\/strong><\/p><p>The Department of Paediatrics and Neonatology specialises in child health. Clinical training, developmental expertise, and compassionate care skills prepare students for comprehensive pediatric practice and neonatal care.<\/p><ul><li><strong>Comprehensive Clinical Exposure: <\/strong>Engaging rotations in pediatric wards and neonatal units, providing firsthand experience with various pediatric specialities<strong>.<\/strong><\/li><\/ul><ul><li><strong>Interactive Learning:<\/strong> Interactive sessions covering developmental milestones, pediatric illnesses, and specialised neonatal care, foster a deep understanding of child health.<\/li><li><strong>Emphasis on Compassionate Care: <\/strong>Focus on empathy in patient interactions, honing communication skills tailored to connect with children and their families.<\/li><li><strong>Diverse Practical Experiences: <\/strong>Opportunities for research and hands-on experiences across different pediatric settings, preparing us for versatile pediatric care.<\/li><\/ul>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},