n/wp-content/uploads/2023/12/Dermatology-min-1-150x150.jpg";s:5:"title";s:15:"Dermatology-min";s:7:"caption";s:0:"";s:3:"alt";s:0:"";s:11:"description";s:0:"";}";}i:153;O:8:"stdClass":3:{s:7:"post_id";s:4:"5781";s:8:"meta_key";s:18:"footer_source_type";s:10:"meta_value";s:1:"d";}i:154;O:8:"stdClass":3:{s:7:"post_id";s:4:"5781";s:8:"meta_key";s:20:"_elementor_edit_mode";s:10:"meta_value";s:7:"builder";}i:155;O:8:"stdClass":3:{s:7:"post_id";s:4:"5781";s:8:"meta_key";s:24:"_elementor_template_type";s:10:"meta_value";s:7:"wp-page";}i:156;O:8:"stdClass":3:{s:7:"post_id";s:4:"5781";s:8:"meta_key";s:18:"_elementor_version";s:10:"meta_value";s:6:"3.25.4";}i:157;O:8:"stdClass":3:{s:7:"post_id";s:4:"5781";s:8:"meta_key";s:15:"_elementor_data";s:10:"meta_value";s:10440:"[{"id":"b651ee6","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":"0","column":"0","row":"0"},"padding":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":""}},"elements":[{"id":"deff3aa","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"66.6666"}},"elements":[{"id":"8dc56b0","elType":"widget","settings":{"editor":"<p>Welcome to the Dermatology Department at Graphic Era Institute of Medical Sciences (GEIMS), where we dedicate ourselves to the science and art of skin care.<\/p>","text_color":"#6B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS Dermatology Department: Nurturing Skin Health and Radiant Lives<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>Step into the realm of skin care excellence at the Dermatology Department of Graphic Era Institute of Medical Sciences (GEIMS). Our mission is to champion the science and art of skin health, providing a sanctuary for education, innovation, and community service.<\/p><p><strong>Holistic Skin Health Approach:<\/strong><\/p><p>At GEIMS, our Dermatology Department adopts a holistic approach, viewing the skin as a mirror of overall well-being. Emphasizing preventive care, therapeutic interventions, and aesthetic enhancements, we lead the way in advancing the field of dermatology.<\/p><p><strong>Cutting-Edge Facilities:<\/strong><\/p><p>Immerse yourself in modern dermatological education with our cutting-edge facilities. Equipped with state-of-the-art consultation rooms, diagnostic tools, and advanced cosmetic treatment areas, our department mirrors real-world dermatological settings. This ensures students gain hands-on experience, preparing them for the intricacies of dermatological practice.<\/p><p><strong>Expert Faculty and Mentorship:<\/strong><\/p><p>At the core of our dermatological excellence is a team of accomplished faculty members\u2014dermatologists, skin specialists, and cosmetic experts. Their diverse expertise offers students a comprehensive learning experience. Beyond clinical skills, our faculty instills a commitment to ethical practice, continuous learning, and patient-centered care. Mentorship extends beyond textbooks, nurturing future dermatologists who are not only skilled but also compassionate and socially responsible.<\/p><p><strong>Comprehensive Curriculum:<\/strong><\/p><p>Delve into a meticulously crafted curriculum designed to provide a profound understanding of dermatological principles and practices. From dermatopathology to aesthetic dermatology, our curriculum ensures graduates are well-equipped to address the diverse needs of individuals seeking dermatological care.<\/p>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":"1","unit":"px","size":"10"},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":""},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":"0","_flex_shrink":"0","sticky":"top","sticky_offset":"100","sticky_effects_offset":"100","sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"center","title_color":"#FFFFFF"},"elements":[],"widgetType":"heading"},{"id":"0cc6981","elType":"widget","settings":{"editor":"<p>Department of Dermatology<\/p>","align":"center","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"700"},"elements":[],"widgetType":"text-editor"},{"id":"c5b2f2e","elType":"widget","settings":{"editor":"<p>Graphic Era Institute of Medical Sciences<br \/>16th Milestone, Chakrata Rd, Dehradun, Uttarakhand 248008<\/p>","align":"center","text_color":"#FFFFFF","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"14","sizes":[]},"typography_font_weight":"500","typography_letter_spacing":{"unit":"px","size":"0","sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"951cf24","elType":"widget","settings":[],"eleme