lue";s:7:"builder";}i:247;O:8:"stdClass":3:{s:7:"post_id";s:4:"5788";s:8:"meta_key";s:24:"_elementor_template_type";s:10:"meta_value";s:7:"wp-page";}i:248;O:8:"stdClass":3:{s:7:"post_id";s:4:"5788";s:8:"meta_key";s:18:"_elementor_version";s:10:"meta_value";s:6:"3.25.4";}i:249;O:8:"stdClass":3:{s:7:"post_id";s:4:"5788";s:8:"meta_key";s:15:"_elementor_data";s:10:"meta_value";s:19911:"[{"id":"b651ee6","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":"0","column":"0","row":"0"},"padding":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":""}},"elements":[{"id":"deff3aa","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"66.6666"}},"elements":[{"id":"8dc56b0","elType":"widget","settings":{"editor":"<p>The General Surgery Department at Graphic Era Institute of Medical Sciences centres on a comprehensive surgical field encompassing anatomy, physiology, and various surgical disciplines. It equips students with specialised expertise in diagnosis, preoperative, operative, and postoperative care.<\/p>","text_color":"#6B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS General Surgery Department: Pioneering Excellence in Surgical Education and Practice<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>The General Surgery department acts as the cornerstone of surgical knowledge, an intricate web intertwining anatomy, physiology, and an array of specialised surgical domains. It serves as an expedition into the core elements of surgery, guiding students through the art of diagnosis, preoperative assessments, intricate procedures, and attentive postoperative care. Within this domain, students unravel the complexities of wound healing, intensive care dynamics, and the nuances of neoplasia. Through immersive experiences and mentorship, this department cultivates not just surgical adeptness, but a profound understanding of the multidimensional landscape of surgery, shaping students into proficient and compassionate surgeons.<\/p><p><strong>\u00a0<\/strong><\/p><p><strong>Key Highlights<\/strong><\/p><p>The Department of General Surgery offers a comprehensive curriculum covering diverse surgical principles. Hands-on training, complication management, and multidisciplinary exposure prepare students for versatile surgical expertise.<\/p><ul><li><strong>Comprehensive Surgical Foundation: <\/strong>Provides a holistic understanding of surgical principles, spanning anatomy, physiology, and various surgical specialities.<\/li><\/ul><ul><li><strong>Multifaceted Learning: <\/strong>Covers a spectrum of surgical components, including wound healing, intensive care, neoplasia, and other critical aspects common to surgical fields.<\/li><\/ul><ul><li><strong>Practical Experience: <\/strong>Offers hands-on exposure to diagnosis, preoperative assessments, intricate procedures, and postoperative care, nurturing surgical skills.<\/li><\/ul><ul><li><strong>Complication Management: <\/strong>Focuses on teaching students how to manage complications effectively, ensuring adeptness in handling challenging surgical scenarios.<\/li><\/ul><ul><li><strong>Mentorship and Guidance:<\/strong> Provides mentorship, fostering a profound understanding of the multidimensional aspects of surge