B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS ENT Department: Nurturing Auditory and Nasal Well-being<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>Step into the realm of comprehensive sensory care at the Ear, Nose, and Throat (ENT) Department of Graphic Era Institute of Medical Sciences (GEIMS). Our commitment is unwavering in providing education, driving innovation, and serving the community in the specialized field of otolaryngology.<\/p><p><strong>Holistic Sensory Health Approach:<\/strong><\/p><p>At GEIMS, our ENT Department adopts a holistic approach, acknowledging the interrelated functions of the ear, nose, and throat. Emphasizing preventive care, precise diagnostics, and therapeutic interventions, we stand at the forefront of advancing otolaryngology.<\/p><p><strong>Cutting-Edge Facilities:<\/strong><\/p><p>Immerse yourself in modern otolaryngology education with our cutting-edge facilities. Outfitted with state-of-the-art examination rooms, diagnostic tools, and surgical suites, our department mirrors real-world ENT settings. This ensures students receive hands-on experience, preparing them for the nuanced challenges of otolaryngological practice.<\/p><p><strong>Expert Faculty and Mentorship:<\/strong><\/p><p>At the heart of our otolaryngological excellence is a team of accomplished faculty members\u2014ENT specialists, surgeons, and researchers. Their diverse expertise provides students with a comprehensive learning experience. Beyond clinical skills, our faculty instills a commitment to ethical practice, continuous learning, and patient-centered care. Mentorship extends beyond textbooks, nurturing future otolaryngologists who are not only skilled but also compassionate and socially responsible.<\/p><p><strong>Comprehensive Curriculum:<\/strong><\/p><p>Delve into a meticulously crafted curriculum designed to provide a profound understanding of otolaryngological principles and practices. From audiology to rhinology, our curriculum ensures graduates are well-equipped to address the diverse needs of individuals seeking ENT care.<\/p>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":"1","unit":"px","size":"10"},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":""},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":"0","_flex_shrink":"0","sticky":"top","sticky_offset":"100","sticky_effects_offset":"100","sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"center","title_color":"#FFFFFF"},"elements":[],"widgetType":"heading"},{"id":"0cc6981","elType":"widget","settings":{"editor":"<p>Department of ENT<\/p>","align":"center","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typogr