:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:18:"banner_source_type";s:10:"meta_value";s:1:"d";}i:300;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:18:"banner_page_banner";s:10:"meta_value";s:1:"1";}i:301;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:22:"banner_page_background";s:10:"meta_value";s:359:"a:9:{s:3:"url";s:70:"https://geims.geu.ac.in/wp-content/uploads/2023/12/Dentistry-min-1.jpg";s:2:"id";s:4:"6276";s:6:"height";s:3:"500";s:5:"width";s:4:"1920";s:9:"thumbnail";s:78:"https://geims.geu.ac.in/wp-content/uploads/2023/12/Dentistry-min-1-150x150.jpg";s:5:"title";s:13:"Dentistry-min";s:7:"caption";s:0:"";s:3:"alt";s:0:"";s:11:"description";s:0:"";}";}i:302;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:18:"footer_source_type";s:10:"meta_value";s:1:"d";}i:303;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:20:"_elementor_edit_mode";s:10:"meta_value";s:7:"builder";}i:304;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:24:"_elementor_template_type";s:10:"meta_value";s:7:"wp-page";}i:305;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:18:"_elementor_version";s:10:"meta_value";s:6:"3.25.4";}i:306;O:8:"stdClass":3:{s:7:"post_id";s:4:"5924";s:8:"meta_key";s:15:"_elementor_data";s:10:"meta_value";s:10203:"[{"id":"b651ee6","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":"0","column":"0","row":"0"},"padding":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":""}},"elements":[{"id":"deff3aa","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"66.6666"}},"elements":[{"id":"8dc56b0","elType":"widget","settings":{"editor":"<p>The Department of Dentistry at GEIMS specialises in oral health, encompassing dental care, treatments, and preventive measures, preparing students for comprehensive dental practice and patient care.<\/p>","text_color":"#6B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS Dentistry Department: Shaping Smiles, Nurturing Oral Health Excellence<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>The Dentistry program is a comprehensive exploration of oral healthcare, integrating scientific principles and clinical proficiency. Students engage in an extensive curriculum encompassing foundational dental sciences and practical clinical applications. Delving into dental anatomy, diagnostics, and a range of treatments, they acquire expertise in restorative, preventive, and surgical dentistry. Notably, the program emphasises patient-centric approaches, fostering effective communication and empathy in dental practice. Clinical training in diverse cases under expert guidance refines their skills, encompassing specialised areas such as orthodontics, endodontics, and periodontics. Beyond crafting adept dental professionals, it instils a commitment to advancing oral health with compassion and excellence in patient care.<\/p><p>\u00a0<\/p><p><strong>Key Highlights<\/strong><\/p><p>The Department of Dentistry offers a comprehensive program that blends scientific knowledge with hands-on clinical experiences. With an emphasis on patient-centric care, students develop effective communication skills and empathy. Practical training occurs in clinics, exposing students to specialities. The program not only shapes proficient dentists but instils a commitment to advancing oral health with compassion and excellence in patient care.<\/p><ul><li><strong>Comprehensive Curriculum<\/strong>: Engages students in both foundational dental sciences and practical clinical applications.<\/li><li><strong>Clinical Proficiency:<\/strong> Provides hands-on training in dental anatomy, diagnostics, and diverse treatments like restorative, preventive, and surgical dentistry.<\/li><li><strong>Patient-Centric Focus:<\/strong> Emphasises effective communication and empathy in patient care, shaping well-rounded dental professionals.<\/li><li><strong>Specialised Exposure:<\/strong> Offers experience in various specialities, including orthodontics, endodontics, and periodontics, broadening students' expertise.<\/li><li><strong>Mentorship and Guidance: <\/strong>Provides expert supervision, refining skills in handling diverse cases and nurturing a commitment to exceptional oral healthcare delivery.<\/li><\/ul>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":"1","unit":"px","size":"10"},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":""},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":"0","_flex_shrink":"0","sticky":"top","sticky_offset":"100","sticky_effects_offset":"100","sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"