n";s:0:"";s:3:"alt";s:0:"";s:11:"description";s:0:"";}";}i:325;O:8:"stdClass":3:{s:7:"post_id";s:4:"5929";s:8:"meta_key";s:18:"footer_source_type";s:10:"meta_value";s:1:"d";}i:326;O:8:"stdClass":3:{s:7:"post_id";s:4:"5929";s:8:"meta_key";s:20:"_elementor_edit_mode";s:10:"meta_value";s:7:"builder";}i:327;O:8:"stdClass":3:{s:7:"post_id";s:4:"5929";s:8:"meta_key";s:24:"_elementor_template_type";s:10:"meta_value";s:7:"wp-page";}i:328;O:8:"stdClass":3:{s:7:"post_id";s:4:"5929";s:8:"meta_key";s:18:"_elementor_version";s:10:"meta_value";s:6:"3.25.4";}i:329;O:8:"stdClass":3:{s:7:"post_id";s:4:"5929";s:8:"meta_key";s:15:"_elementor_data";s:10:"meta_value";s:10573:"[{"id":"b651ee6","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":"0","column":"0","row":"0"},"padding":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":""}},"elements":[{"id":"deff3aa","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"66.6666"}},"elements":[{"id":"8dc56b0","elType":"widget","settings":{"editor":"<p>The Department of Respiratory Medicine at GEIMS specialises in diagnosing and treating respiratory conditions, offering comprehensive education in managing lung diseases and advancing respiratory healthcare.<\/p>","text_color":"#6B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS Respiratory Medicine Department: Nurturing Pulmonary Excellence<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>The Department of Respiratory Medicine stands as a cornerstone in understanding and managing respiratory ailments. Its comprehensive curriculum encompasses the spectrum of respiratory disorders, from common conditions like asthma and COPD to rare lung diseases. Students explore diagnostic techniques, therapeutic interventions, and advancements in pulmonary care. The department focuses on respiratory physiology, pathology, and the intricate mechanisms underlying respiratory illnesses. Hands-on clinical experiences in outpatient clinics, pulmonary function labs, and critical care units provide invaluable exposure to diverse patient cases. With a commitment to fostering expertise in pulmonary health, this department equips future healthcare professionals to address the complexities of respiratory medicine adeptly and compassionately.<\/p><p><strong>\u00a0<\/strong><\/p><p><strong>Key Highlights<\/strong><\/p><p>The future in Respiratory Medicine is promising, with ongoing advancements in technology, diagnostics, and therapeutics. Innovations in targeted therapies, personalised medicine, and telemedicine are expected to reshape the field.<\/p><ul><li><strong>Diagnostic Proficiency<\/strong>: Equips students with skills in diagnostic procedures like pulmonary function tests and imaging for accurate disease assessment.<\/li><li><strong>Therapeutic Expertise:<\/strong> Provides insights into various treatment modalities including medications, pulmonary rehabilitation, and advanced interventions like bronchoscopy.<\/li><li><strong>Clinical Exposure: <\/strong>Offers hands-on experience in outpatient clinics, pulmonary function labs, and intensive care units, facilitating exposure to diverse patient cases.<\/li><li><strong>Research Opportunities:<\/strong> Encourages research in cutting-edge advancements, fostering innovation in the field of respiratory medicine.<\/li><li><strong>Interdisciplinary Collaboration:<\/strong> Emphasises collaboration with other specialities for holistic patient care.<\/li><\/ul>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":"1","unit":"px","size":"10"},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":""},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":"0","_flex_shrink":"0","sticky":"top","sticky_offset":"100","sticky_effects_offset":"100","sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"center","title_color":"#FFFFFF"},"elements":[],"widgetType":"heading"},{"id":"0cc6981","elType":"widget","settings":{"editor":"<p>Department of Respiratory Medicine<\/p>","align":"center","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"700"},"elements":[],"widgetType":"text-editor"},{"id":"c5b2f2e","elType":"widget","settings":{"editor":"<p>Graphic Era Institute of Medical Sciences<br \/>16th Milestone, Chakrata Rd, Dehradun, Uttarakhand 248008<\/p>","align":"center","text_color":"#FFFFFF","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"14","sizes":[]},"typography_font_weight":"500","typography_letter_spacing":{"unit":"px","size":"0","sizes":[]}},"elements":[],"widgetType":"text-edit