graphy_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS Pharmacology Department: Nurturing Medicinal Expertise for Health and Healing<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":"21","sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":"2","sizes":[]},"gap":{"unit":"px","size":"2","sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>The Pharmacology Department engages students in exploring medicinal compounds and their impacts on the human system. Nurturing aspiring pharmacologists emphasises understanding compound mechanisms, effects, and their applications in healthcare. This comprehensive program equips individuals with essential proficiencies in pharmaceuticals, research, therapeutic development, and healthcare administration. Through rigorous training and practical experience, students acquire expertise in compound interactions, preparing them to contribute significantly to medical advancements and pharmaceutical innovation. The department's commitment to cultivating adept professionals aligns with the evolving pharmaceutical landscape, offering opportunities for impactful roles in the dynamic healthcare realm.<\/p><p>\u00a0<\/p><p><strong>Key Highlights<\/strong><\/p><p>The Pharmacology Department at GEIMS delves into medicinal compounds' effects and mechanisms, preparing students for practical applications in healthcare. Its comprehensive curriculum opens doors to diverse career paths in pharmaceuticals, research, therapeutic development, and healthcare management.<\/p><p>Moreover, the department emphasises innovative research, aligning students with the forefront of pharmaceutical advancements.<\/p><ul><li><strong>Study of Medicinal Compounds:<\/strong> In-depth exploration of compounds' effects on the human system.<\/li><li><strong>Focus on Compound Mechanisms:<\/strong> Understanding how compounds interact within the body.<\/li><li><strong>Practical Application in Healthcare:<\/strong> Learning to apply compound knowledge in clinical settings.<\/li><li><strong>Diverse Career Opportunities:<\/strong> Pathways in pharmaceuticals, research, therapeutic development, and healthcare management.<\/li><li><strong>Cutting-edge Research Emphasis: <\/strong>Engaging in innovative research shaping future pharmaceutical advancements.<\/li><\/ul>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":"1"},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":"1","unit":"px","size":"10"},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":""},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":"0","_flex_shrink":"0","sticky":"top","sticky_offset":"100","sticky_effects_offset":"100","sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"center","title_color":"#FFFFFF"},"elements":[],"widgetType":"heading"},{"id":"0cc6981","elType":"widget","settings":{"editor":"<p>Department of Pharmacology<\/p>","align":"center","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"700"},"elem