_color":"#6B6B6B","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":21,"sizes":[]},"typography_font_weight":"300"},"elements":[],"widgetType":"text-editor"},{"id":"e682435","elType":"widget","settings":{"editor":"<p><strong>GEIMS Forensic Medicine Department: Pioneering Excellence in Healthcare Leadership<\/strong><\/p>","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":21,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1be8986","elType":"widget","settings":{"text":"Divider","color":"#65CC33","weight":{"unit":"px","size":2,"sizes":[]},"gap":{"unit":"px","size":2,"sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"95d683c","elType":"widget","settings":{"editor":"<p>The Forensic Medicine Department immerses students in medico-legal investigations, autopsy procedures, and forensic analysis techniques. Focused on cultivating future forensic experts, the curriculum emphasises practical skills and theoretical knowledge essential for this specialised field. It paves paths for diverse career opportunities in forensic pathology, criminal investigations, and legal consultancy. Through rigorous training and exposure to real-life cases, students develop expertise in evidence interpretation and crime scene analysis. The department's commitment to nurturing adept professionals aligns with the evolving landscape of forensic sciences, preparing students for impactful roles in law enforcement, justice systems, and scientific research.<\/p><p>\u00a0<\/p><p><strong>Key Highlights<\/strong><\/p><p>The Forensic Medicine Department is a hub for medico-legal investigations, offering expertise in autopsy procedures, forensic analysis techniques, and specialised skill development. Its comprehensive curriculum shapes students for diverse careers in forensic pathology, criminal investigations, and legal advisory roles, fostering adept professionals crucial in the evolving realm of forensic sciences.<\/p><ul><li><strong>Medico-Legal Investigations:<\/strong> In-depth training in conducting forensic inquiries for legal purposes.<\/li><li><strong>Autopsy Procedures Expertise:<\/strong> Hands-on learning in post-mortem examinations and analysis techniques.<\/li><li><strong>Forensic Analysis Techniques:<\/strong> Mastery in analysing evidence and interpreting crime scene findings.<\/li><li><strong>Specialised Skill Development: <\/strong>Acquiring expertise in evidence interpretation and forensic pathology.<\/li><li><strong>Career Diversification: <\/strong>Opportunities in forensic pathology, criminal investigations, and legal advisory roles.<\/li><\/ul>","text_color":"#7A7A7A"},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"5aefa4e","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"3c0f806","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"flex_gap":{"column":"10","row":"10","isLinked":true,"unit":"px","size":10},"background_background":"classic","background_color":"#3A3A3A","padding":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":false},"_flex_align_self":"flex-start","_flex_size":"none","_flex_grow":0,"_flex_shrink":0,"sticky":"top","sticky_offset":100,"sticky_effects_offset":100,"sticky_parent":"yes","animation":"slideInUp","animation_duration":"fast"},"elements":[{"id":"e7017ae","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"496f51d","elType":"widget","settings":{"title":"Department Info","header_size":"h5","align":"center","title_color":"#FFFFFF"},"elements":[],"widgetType":"heading"},{"id":"0cc6981","elType":"widget","settings":{"editor":"<p>Department of Forensic Medicine<\/p>","align":"center","text_color":"#65CC33","typography_typography":"custom","typography_font_family":"Roboto","typogr