it":"px","size":28,"sizes":[]},"_padding":{"unit":"px","top":"100","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"blockquote"},{"id":"193c078","elType":"widget","settings":{"blockquote_skin":"clean","blockquote_content":"","author_name":"Prof. (Dr.) Kamal Ghanshala, President - Graphic Era Group of Institutions","tweet_button":"","tweet_button_label":"Tweet","content_typography_typography":"custom","content_typography_font_size":{"unit":"px","size":28,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"blockquote"}],"isInner":true},{"id":"c16390f","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"background_background":"classic","background_color":"#FFFFFF","background_color_b":"#FFFFFF","background_image":{"url":"https:\/\/geims.geu.ac.in\/wp-content\/uploads\/image\/chairman-sir-image.png","id":11927,"size":"","alt":"","source":"library"},"background_size":"cover"},"elements":[{"id":"6ed692a","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"fbc4f4f","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"},{"id":"bc69198","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"}],"isInner":true}],"isInner":false},{"id":"8f3d0c2","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"6dbbecb","elType":"widget","settings":{"text":"Divider","color":"#7FC540","weight":{"unit":"px","size":2.8,"sizes":[]},"_margin":{"unit":"px","top":"-35","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"divider"}],"isInner":false},{"id":"63b3921","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"c24e5ed","elType":"widget","settings":{"editor":"<h4>\u00a0<\/h4><h4><strong>Profile of Prof.(Dr.) Kamal Ghanshala<\/strong><\/h4><p>\u00a0<\/p><ul><li>Prof.(Dr) Kamal Ghanshala is an engineer, entrepreneur and a philanthropist and posseses excellent academic credentials with Bachelor\u2019s and Master's degree in Computer Science &amp; Engineering and Doctoral degree in Computer Science from Kumaon University, Nainital. GEU is a realization of his vision to put on Doon landscape a university that is all round enabler of excellence for youth.<\/li><li>Prof. Ghanshala is a proactive chancellor and a teacher par excellence. He is inarguably, one of the leading experts in teaching of Computer Aided Design (CAD) and \u2018C\u2019 language. His plethora of knowledge is not just confined to the four walls of university but also reflected in many research papers he has written and for which he has been felicitated, at national and international levels, such as in Croatia, Denmark, Johannesburg, Turkey, London, Paris Germany and Thailand. He has received wide spread recognition for his leadership qualities and management acumen. He is also an avid sportsman.Under his dynamic leadership Graphic Era is at the cutting edge of educational innovations, new ideas and new practices.<\/li><\/ul>"},"elements":[],"widgetType":"text-editor"},{"id":"488477d","elType":"widget","settings":{"editor":"<h4>\u00a0<\/h4><h4><strong>Awards &amp; Achievements<\/strong><\/h4><p>\u00a0<\/p><ul><li>Received Edupreneurs Award-2017 for his contribution to the cause of quality education. The award was presented to him by Mr. Pranab Mukherjee, the former President of India.<\/li><li>Received Distinguished Educationist Award -2016, conferred at The Icons Of Learning Conclave by Business Excellence Research Group (BERG) Singapore, for his immense contribution to the management of quality education and excellent teaching practices.<\/li><li>Conferred the prestigious Best Manager of the Year Award in Science and Education Sphere 2015 by Europe Business Assembly in the prestigious International Summit of Leaders held at Oxford Town Hall, Oxford City United Kingdom on 15th December 2015.<\/li><li>Honored as the Program Committee Chair for 4th International Conference on \"Computer Communication and Management (ICCCM 2014)\" organized in Paris, France on May 21-22, 2014.<\/li><li>Conferred Best Paper Presentation award at the \u2018International Conference on Intelligent Systems, Data Mining and Information Technology (ICIDIT), April 2014\u2019, at Bangkok, Thailand.<\/li><li>Received Excellent Paper Presentation Award on IT - Initiatives for Empowering Difficult Geographies, at 35th International Conference on Information Technology Interfaces in Cavtat, Croatia \u2013 June 24-27, 2013.<\/li><li>Awarded Certificate for Excellent Paper at the 3rd International Conference on Computer Communication and Management (ICCCM) 2013\u2019,at Copenhagen, Denmark, May 19-20, 2013.<\/li><li>Conferred prestigious Dr B. C. Roy Award for social services related to health causes, in 2010.<\/li><li>Conferred the International Gold Star Millennium Award at the International Conference on \u2018Celebrating the Global Indian\u2019, by His Excellency Mr. Korn Dabbaransi, Former Deputy Prime Minister of Thailand in 2008.<\/li><li>Conferred the Uttarakhand Ratan Award for outstanding contribution to quality Technical and Higher education in Uttarakhand, in 2007.<\/li><\/ul>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}]";}i:550;O:8:"stdClass":3:{s:7:"post_id";s:4:"6683";s:8:"meta_key";s:10:"_edit_lock";s:10:"meta_value";s:12:"1781004475:5";}i:551;O:8:"stdClass":3:{s:7:"post_id";s:4:"6683";s:8:"meta_key";s:10:"_edit_last";s:10:"meta_value";s:1:"4";}i:552;O:8:"stdClass":3:{s:7:"post_id";s:4:"6683";s:8:"meta_key";s:22:"banner_page_background";s:10:"meta_value";s:387:"a:9:{s:3:"url";s:70:"https://geims.geu.ac.in/wp-content/uploads/2024/07/geims-bg-01-min.jpg";s:2:"id";s:4:"7442";s:6:"height";s:3:"880";s:5:"width";s:4:"1920";s:9:"thumbnail";s:78:"https://geims.geu.ac.in/wp-content/uploads/2024/07/geims-bg-01-min-150x150.jpg";s:5:"title";s:15:"geims-bg-01-m