ze":28,"sizes":[]},"_padding":{"unit":"px","top":"100","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"blockquote"},{"id":"193c078","elType":"widget","settings":{"blockquote_skin":"clean","blockquote_content":"","author_name":"Dr. Vijay Kumar Saraswat, Chancellor, Graphic Era (Deemed to be University)","tweet_button":"","tweet_button_label":"Tweet","content_typography_typography":"custom","content_typography_font_size":{"unit":"px","size":28,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"blockquote"}],"isInner":true},{"id":"c16390f","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"33.3333"},"background_background":"classic","background_color":"#FFFFFF","background_color_b":"#FFFFFF","background_image":{"url":"https:\/\/geims.geu.ac.in\/wp-content\/uploads\/2023\/12\/chancellor-sir.webp","id":6153,"size":"","alt":"","source":"library"},"background_size":"cover"},"elements":[],"isInner":true}],"isInner":false},{"id":"8f3d0c2","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"6dbbecb","elType":"widget","settings":{"text":"Divider","color":"#7FC540","weight":{"unit":"px","size":2.8,"sizes":[]},"_margin":{"unit":"px","top":"-35","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"divider"}],"isInner":false},{"id":"63b3921","elType":"container","settings":{"flex_direction":"column"},"elements":[{"id":"c24e5ed","elType":"widget","settings":{"editor":"<h4>\u00a0<\/h4><h4><strong>Profile of Dr. Vijay Kumar Saraswat<\/strong><\/h4><p>\u00a0<\/p><p>Dr. Vijay Kumar Saraswat, a luminary in the realm of Indian science and defence, has dedicated over four decades to groundbreaking research and innovation.<\/p><p>He is a member of NITI Aayog and the co-chair for the Prime Minister\u2019s Science, Technology and Innovation Advisory Council (PM-STIAC)<\/p><p>His journey, spanning multiple domains in both basic and applied sciences, is marked by unparalleled accomplishments. Born on May 25, 1949, in Gwalior, Dr. Saraswat\u2019s academic prowess began with his engineering studies in his hometown. Subsequently, he pursued a Master of Engineering at the prestigious Indian Institute of Science in Bangalore, culminating in a Ph.D. from Osmania University.<\/p><p>Throughout his illustrious career, Dr. Saraswat held several pivotal positions, each contributing to the advancement of India\u2019s defense capabilities. He evolved from a scientist to the Scientific Adviser to the Defence Minister, Director to Director-General of the Defence Research and Development Organisation (DRDO), and Secretary to the Department of Defence Research and Development. His indomitable spirit and visionary approach have set him apart as a scientist, innovator, and technologist.<\/p><p>Dr. Saraswat has been an architect of cutting-edge innovations, credited with indigenous developments that have fortified India\u2019s national security. Notably, he spearheaded the creation of missiles like Prithvi, Dhanush, Prahaar, and Agni-5, alongside the establishment of a two-tiered Ballistic Missile Defence system. Under his leadership, DRDO achieved the initial operational clearance for the Light Combat Aircraft Tejas and played a pivotal role in launching the nuclear submarine INS Arihant.<\/p><p>As the Secretary of DRDO, Dr. Saraswat played a pivotal role in enhancing India\u2019s strategic capabilities. This included establishing infrastructure for strategic nuclear assets to support the Nuclear Doctrine, conducting flight evaluations for long-range subsonic cruise missiles, developing long-range radars for tracking incoming enemy ballistic missiles, and creating a command, control, and communication network to safeguard the National Capital Region against ballistic missile threats. Furthermore, he initiated the Cyber Security Research and Development Centre, focusing on offensive and defensive cybersecurity technologies.<\/p><p>Dr. Saraswat\u2019s contribution extends beyond defence research. He served as the Homi Bhabha Chair Professor and Consultant to IOCL R&amp;D, where he paved the way for alternative energy systems, including clean coal technologies, high-efficiency concentrated solar power systems, and a bioenergy- and hydrogen-based economy.<\/p><p>As the Chairman of NTPC R&amp;D Advisory Council, he developed alternative energy technology plans, emphasizing clean coal technologies and advanced ultra-supercritical thermal power plants to reduce greenhouse emissions significantly.<\/p><p>Notably, Dr. Saraswat\u2019s visionary initiatives included the establishment of the Photonics Valley Corporation in Telangana, which focuses on developing silicon photonics technology for next-generation networks. He also chaired the Committee for Development of Indian Microprocessors, contributing to the advancement of the M-Processor configuration for IoT, Smart Cities, and other ICT applications.<\/p><p>Moreover, he conceptualized the Indian Railway Research Institute (Shresththa), aiming to boost indigenous designs and manufacturing, particularly in high-speed rail systems and dedicated freight corridors, thereby ushering in a new era of R&amp;D for Indian Railways.<\/p><p>As a Member of NITI Aayog, Dr. Saraswat introduced the \u2018Methanol Economy\u2019 program, facilitating transportation, energy generation, and chemical production. This initiative brought production agencies, academic institutions, and petro-refineries together, promoting R&amp;D in gasification of high ash content Indian coal.<\/p><p>Dr. Saraswat chaired committees for the growth of technical textiles and framing a \u2018Roadmap for Make in India in Body Armour.\u2019 His insights were utilised for the formulation of BIS standards on body armour.<\/p><p>He led an empowered technical advisory committee for the development of national supercomputing systems, shaping the configuration and development strategy for this crucial program.<\/p><p>Dr. Vijay Kumar Saraswat\u2019s dedication to research, innovation, and visionary leadership has left an indelible mark on India\u2019s scientific and technological landscape. As he takes on the role of Chancellor at Graphic Era Deemed to be University, his wealth of experience and commitment to academic excellence promises to guide the institution towards even greater heights, ensuring a bright future for the entire student community.<\/p>"},"elements":[],"widgetType":"text-editor"},{"id":"488477d","elType":"widget","settings":{"editor":"<h4>\u00a0<\/h4><h4><strong>Awards &amp; Achievements<\/strong><\/h4><p>\u00a0<\/p><ul><li>Padmabhushan (2013)<\/li><li>Padmashri (1998)<\/li><li>Vikram Sarabhai Memorial Award from Indian Science Congress (2011)<\/li><li>APJ Abdul Kalam Lifetime Achievement Award<\/li><li>Lifetime Achievement Award by Ramakrishna-Vivekananda International Foundation, New Delhi<\/li><li>Prof Jai Krishna Memorial Award by Indian National Academy of Engineering (INAE)<\/li><li>Dr Y Nayudamma Memorial Gold Medal for the year 2011 by AP Science Congress<\/li><li>Jawaharlal Nehru S&amp;T Award (2009) by Govt of Madhya Pradesh<\/li><li>FICCI Annual Award<\/li><li>ARYABHATA Award (2011) from Astronautical Society of India<\/li><li>National Aeronautical Prize (1998)<\/li><li>Honorary Doctorates from more than 25 universities<\/li><\/ul>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}]";}i:593;O:8:"stdClass":3:{s:7:"post_id";s:4:"6696";s:8:"meta_key";s:10:"_edit_lock";s:10:"meta_value";s:12:"1749468849:4";}i:594;O:8:"stdClass":3:{s:7:"post_id";s:4:"6696";s:8:"meta_key";s:10:"_edit_last";s:10:"meta_value";s:1:"4";}i:595;O:8:"stdClass":3:{s:7:"post_id";s:4:"6696";s:8:"meta_key";s:22:"banner_page_background";s:10:"meta_value";s:387:"a:9:{s:3:"url";s:70:"https://geims.geu.ac.in/wp-content/uploads/2024/07/geims-bg-01-min.jpg";s:2:"id";s:4:"7442";s:6